@import "tailwindcss";
@import "tw-animate-css";
@import "./theme.css";

@layer base {
  html { -webkit-text-size-adjust: 100%; }
  body { min-height: 100dvh; overflow-x: clip; -webkit-font-smoothing: antialiased; }
}

/* Hiện dần khi cuộn tới (khu công khai) — xem components/public/Reveal.tsx. */
@utility reveal {
  &[data-reveal] {
    transition:
      opacity 600ms var(--anim-ease-out) var(--reveal-delay, 0ms),
      translate 600ms var(--anim-ease-out) var(--reveal-delay, 0ms);
  }
  &[data-reveal="hidden"] {
    opacity: 0;
    translate: 0 1.5rem;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-reveal] {
      transition: none;
    }
  }
}

/* Khu công khai có nhiều người lớn tuổi đọc: nâng thang cỡ chữ lên một bậc so với kit. Đặt ở :root (qua :has) để
 * cả hộp chọn/popup render ngoài khung trang cũng dùng cùng thang. */
:root:has(.public-scale) {
  --fs-micro: 12px;
  --fs-tiny: 14px;
  --fs-caption: 14px;
  --fs-label: 14px;
  --fs-meta: 14px;
  --fs-small: 15px;
  --fs-body: 16px;
  --fs-control: 15px;
  --fs-base: 16px;
  --fs-emph: 18px;
  --fs-lead: 18px;
  --fs-title: 21px;
  --fs-heading: 26px;
  --fs-display: 38px;
  --text-xs: 13px;
  --text-sm: 15px;
  --text-lg: 18px;
  --text-xl: 21px;
}
.public-scale { font-size: var(--text-base); }

/* Fully remove the black outline / focus ring / tap highlight when touching or clicking a chart */
[data-slot="chart"],
[data-slot="chart"] *,
.recharts-wrapper,
.recharts-wrapper *,
.recharts-surface,
.recharts-surface *,
.recharts-responsive-container,
.recharts-responsive-container * {
  outline: none !important;
  box-shadow: none !important;
  -webkit-tap-highlight-color: transparent !important;
  -webkit-focus-ring-color: transparent !important;
}
